def transform(grid):
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Find the separator row (all same non-zero value)
    sep_row = -1
    for i in range(n):
        val = grid[i][0]
        if val != 0 and all(grid[i][j] == val for j in range(m)):
            sep_row = i
            break

    # Get top and bottom sections
    if sep_row > 0:
        top_section = grid[:sep_row]
    else:
        top_section = grid

    # Find the separator for bottom section (usually the row after top)
    # Bottom section is after the separator row
    bottom_section = []
    if sep_row < n - 1:
        bottom_section = grid[sep_row + 1:]
    # If no separator, check if we have enough rows  
    else:
        bottom_section = grid[1:] if n > 1 else [grid[0]]

    # Transform: output[i][j] = 2 if top[i][j] > 0 AND bottom[i][j] == 0, else 0
    if sep_row > 0 and len(top_section) == len(bottom_section):
        result = []
        for i in range(len(top_section)):
            row = []
            for j in range(m):
                if top_section[i][j] > 0 and bottom_section[i][j] == 0:
                    row.append(2)
                else:
                    row.append(0)
            result.append(row)
        return result
    else:
        # Fallback: simple convert positive to 2
        result = []
        for row in top_section:
            new_row = [2 if cell > 0 else 0 for cell in row]
            result.append(new_row)
        return result
